def can_sort_by_reversing_one_subarray(cards):
    n = len(cards)
    start, end = -1, -1
    count = 0

    for i in range(1, n):
        if cards[i] < cards[i - 1]:
            if count == 0:
                start = i - 1
            count += 1
            end = i

    if count > 1:
        return "impossible"

    if start != -1 and end != -1:
        if start > 0 and cards[start - 1] > cards[end]:
            return "impossible"
        if end + 1 < n and cards[start] > cards[end + 1]:
            return "impossible"

    return f"{start + 1} {end + 1}"

