def reverse_subarray_to_sort(arr):
    n = len(arr)
    left = -1
    right = -1

    for i in range(1, n):
        if arr[i] < arr[i - 1]:
            if left == -1:
                left = i - 1
            right = i

    if left == -1:
        return "impossible"

    arr[left:right+1] = reversed(arr[left:right+1])

    for i in range(1, n):
        if arr[i] < arr[i - 1]:
            return "impossible"

    return f"{left + 1} {right + 1}"

